# Writes the generated hedra command files of the reef's environment: seabed.txt, bubbles.txt,
# fish.txt (keys for three fish on an orbit). Hand-written: coral_branch.txt, coral_brain.txt,
# coral_fan.txt, rock.txt, kelp.txt. Run from models/env: /usr/bin/python3 make_env.py.
# Up Z, front -Y (hedra). Colours exact BLK AQU4 (sRGB 0..1).
import math, random

C = {"navy": (0.0, 0.169, 0.349), "blue": (0.0, 0.373, 0.549),
     "aqua": (0.0, 0.725, 0.745), "pale": (0.624, 0.957, 0.898)}
def col(n, emit=False):
    r, g, b = C[n]
    s = f"--base-color {r:.3f} {g:.3f} {b:.3f}"
    return s + (f" --emission {r:.3f} {g:.3f} {b:.3f}" if emit else "")

# ---- seabed: a 14-sided slab 14 m across, its top fanned and subdivided into a gentle, uneven sand
# floor with the ripple texture over the whole top; rock sides; the far edge dissolves in the fog.
R = 7.0
open("seabed.txt", "w").write(f"""# Seabed: a 14-sided slab {2*R:.0f} m across (top at z 0), the top a gently uneven sand floor carrying
# one 64 px ripple texture over the whole disc (0.22 m a texel), rock sides. Generated by make_env.py.
new
material new Sand --base-color 1 1 1 --no-slot
material new Rock {col('blue')} --no-slot
add mesh cylinder --name Seabed --vertices 14 --radius {R} --depth 0.6 --location 0 0 -0.3
apply --location
material assign Rock
mode edit
select face where "normal.z < -0.9"
delete only-faces
select face where "normal.z > 0.9"
poke
select face where "normal.z > 0.5"
subdivide --cuts 5
select vert where "pos.z > -0.01 && sqrt(pos.x*pos.x + pos.y*pos.y) > 1.6 && sqrt(pos.x*pos.x + pos.y*pos.y) < {R - 0.3}"
randomize --amount 0.12 --seed 6
select face where "normal.z > 0.5"
material assign Sand
uv project-from-view top --scale-to-bounds
mode object
material texture Sand base-color ../../art/textures/sand_64.png
shade flat
export seabed.glb
""")

# ---- bubbles: three columns rising out of the sand (one through the clam), two identical 5 m
# fields stacked: the lower one starts under the sand (hidden inside the seabed), the upper one
# leaves the top of the frame; the object rises one field per 6 s loop: seamless.
random.seed(3)
H, LOOP = 5.0, 72
cols = [(0.0, 0.0), (2.6, 1.4), (-2.4, -0.6)]
pts = []
for cx, cy in cols:
    for i in range(7):
        pts.append((cx + random.uniform(-0.15, 0.15), cy + random.uniform(-0.15, 0.15),
                    random.uniform(0, H), random.choice([0.07, 0.09, 0.11])))
b = [f"""# Bubbles: three columns rising out of the sand (the first one through the clam), two identical
# {H:.0f} m fields stacked, rising one field per {LOOP // 12} s: the lower field starts under the sand (hidden
# inside the seabed), the upper one leaves the top of the frame, so the loop has no seam.
# Columns at (0, 0), (2.6, 1.4), (-2.4, -0.6) in the scene's top view. Generated by make_env.py.
new
fps 12
frame range 0 {LOOP}
material new Bubble {col('pale', True)} --no-slot
"""]
names = []
for k in (0, 1):
    for i, (x, y, z, r) in enumerate(pts):
        n = f"B{i}_{k}"; names.append(n)
        b.append(f"add mesh ico-sphere --name {n} --subdivisions 1 --radius {r} --location {x:.3f} {y:.3f} {z - H * (1 - k):.3f}\n")
b.append("select " + " ".join(names) + f"""
active B0_0
join
rename B0_0 Bubbles
material assign Bubble
cursor set 0 0 0
origin set --to cursor
set location 0 0 0
keyframe insert --channels loc --frame 0
set location 0 0 {H}
keyframe insert --channels loc --frame {LOOP}
keyframe interpolation linear --all
frame set 0
export bubbles.glb --bake-animations
""")
open("bubbles.txt", "w").write("".join(b))

# ---- fish: Orbit (empty, one turn in 12 s) > three fish at different radii, heights and angles,
# each a Body with a Tail child that flicks. Rigid: 6 bones a school.
LOOPF = 144
fish = [(3.2, 1.6, 0), (3.7, 2.1, 25), (2.9, 2.4, 50)]   # radius, height, angle (degrees)
f = [f"""# A school of three fish circling the reef: Orbit (an empty, one turn in {LOOPF // 12} s, counter-clockwise
# seen from above) > Fish bodies at radius 2.9-3.7 m, heights 1.6-2.4 m > a Tail on each that flicks
# +-30 degrees every 4 frames (12 fps). Bodies and tails are joined parts: 6 bones. The fish face -Y at
# rest; each is turned 180 + its angle so it swims forward along its circle. Sizes exaggerated for the splat grid (body 0.62 long).
# Generated by make_env.py.
new
fps 12
frame range 0 {LOOPF}
material new Scale {col('pale')} --no-slot
material new Fin {col('aqua')} --no-slot
add empty --name Orbit --location 0 0 0
"""]
for i, (r, h, a) in enumerate(fish):
    f.append(f"""add mesh ico-sphere --name Body{i} --subdivisions 1 --radius 0.5 --location 0 0 0
scale 0.2 0.62 0.34
apply --scale
material assign Scale
add mesh cube --name Dorsal{i} --size 1 --location 0 0.04 0.19
scale 0.06 0.24 0.14
apply
material assign Fin
select Dorsal{i} Body{i}
active Body{i}
join
add mesh cube --name Tail{i} --size 1 --location 0 0 0
scale 0.06 0.3 0.34
apply --scale
material assign Fin
active Tail{i}
mode edit
select all
translate 0 0.15 0
select vert where "pos.y > 0.2"
scale 1 1 1.5
mode object
select Tail{i}
set location 0 0.3 0
select Tail{i} Body{i}
parent set Body{i}
select Body{i}
set location {r * math.cos(math.radians(a)):.3f} {r * math.sin(math.radians(a)):.3f} {h}
set rotation 0 0 {a + 180:.1f}
select Body{i} Orbit
parent set Orbit
""")
f.append(f"""select Orbit
frame set 0
set rotation 0 0 0
keyframe insert --channels rot
frame set {LOOPF}
set rotation 0 0 360
keyframe insert --channels rot
""")
for i in range(3):
    f.append(f"select Tail{i}\n")
    for k in range(0, LOOPF + 1, 4):
        ang = 30 if (k // 4 + i) % 2 == 0 else -30
        f.append(f"frame set {k}\nset rotation 0 0 {ang}\nkeyframe insert --channels rot\n")
f.append("""keyframe interpolation linear --all
frame set 0
select all
shade flat
export fish.glb --bake-animations
""")
open("fish.txt", "w").write("".join(f))
print("wrote seabed.txt bubbles.txt fish.txt")
